function permissionModule(pathname){if(/^\/(customers|vehicles|search)(\/|$)/.test(pathname))return 'customers';if(/^\/(bookings|resources)(\/|$)/.test(pathname))return 'bookings';if(/^\/(work-orders|operations|time-entries|estimates|customer\/approve)(\/|$)/.test(pathname))return 'orders';if(/^\/(inventory|suppliers|purchases|purchase-order-lines)(\/|$)/.test(pathname))return 'inventory';if(/^\/invoices(\/|$)/.test(pathname))return 'billing';if(/^\/reports(\.csv)?$/.test(pathname))return 'reports';if(/^\/team(\/|$)/.test(pathname))return 'team';if(/^\/(settings|permissions)(\/|$)/.test(pathname))return 'settings';if(/^\/privacy-requests(\/|$)/.test(pathname))return 'privacy';return null;}
function allow(...roles) { return async(req,res,next) => {const role=req.session.user?.role;if(!roles.includes(role))return res.status(403).send(page('Accesso negato','<section class="card"><p>Non hai i permessi per questa funzione.</p></section>',req.session.user));if(role==='owner'||role==='admin')return next();const module=permissionModule(req.path);if(!module)return next();try{const setting=await pool.query('SELECT allowed FROM role_module_permissions WHERE role=$1 AND module=$2',[role,module]);if(setting.rowCount&&!setting.rows[0].allowed)return res.status(403).send(page('Accesso limitato','<section class="card"><p>L’accesso a questa sezione è stato disattivato dall’amministratore dell’officina.</p></section>',req.session.user));next();}catch(error){next(error);}}; }
function flash(req, value) { req.session.flash = value; }
function takeFlash(req) { const value=req.session.flash; delete req.session.flash; return value ? `<div class="notice">${esc(value)}</div>` : ''; }
