const intakeStations={exterior:['front','front_right','right','rear_right','rear','rear_left','left','front_left'],interior:['interior_front','interior_rear'],dashboard:['dashboard']};
const reconstructionStages={queued:'in attesa',preparing:'preparazione foto',aligning:'ricerca dettagli',matching:'abbinamento scatti', 'camera-solving':'allineamento fotocamere','image-preparation':'preparazione scena','scene-import':'importazione scena','dense-reconstruction':'ricostruzione geometria','mesh-generation':'creazione mesh','mesh-refinement':'rifinitura mesh',texturing:'applicazione texture','glb-export':'esportazione modello',complete:'completata',failed:'non riuscita'};
const intakeLabels={front:'Anteriore',front_right:'Anteriore destro',right:'Fianco destro',rear_right:'Posteriore destro',rear:'Posteriore',rear_left:'Posteriore sinistro',left:'Fianco sinistro',front_left:'Anteriore sinistro',interior_front:'Interni anteriori',interior_rear:'Interni posteriori',dashboard:'Cruscotto'};
const defaultRepairTerms=`CONDIZIONI DI RIPARAZIONE — modello da verificare con i consulenti dell’officina\n\n1. Il cliente descrive i sintomi e autorizza esclusivamente la diagnosi e le lavorazioni espressamente indicate e approvate. La data di riconsegna eventualmente indicata è una stima soggetta a diagnosi, disponibilità dei ricambi e autorizzazioni.\n2. Se la diagnosi evidenzia lavori, ricambi o costi ulteriori, l’officina informa il cliente e chiede una nuova autorizzazione prima di procedere. Non si eseguono lavori extra senza consenso, salvo interventi urgenti indispensabili autorizzati separatamente e documentati.\n3. Ricambi, manodopera, imposte, eventuali acconti e prezzo concordato sono indicati nel preventivo o nella sua variazione approvata. Il preventivo ha la validità riportata nel documento; le variazioni sono sottoposte nuovamente al cliente.\n4. Il cliente comunica difetti noti, dispositivi antifurto, modalità di avviamento e limitazioni del veicolo, consegna le chiavi necessarie e segnala oggetti di valore. L’officina registra condizioni e dotazioni visibili all’ingresso e custodisce il mezzo con ragionevole diligenza.\n5. Il cliente sceglie separatamente se autorizzare una prova su strada, limitata alle verifiche pertinenti all’intervento e svolta da personale incaricato nel rispetto delle regole applicabili. Se la rifiuta, l’officina non effettua il test dinamico e alcuni sintomi o risultati potrebbero non essere verificabili nelle condizioni reali di marcia. Il rifiuto sarà riportato nella scheda e non costituisce rinuncia generale a diritti, garanzie o responsabilità, né esclude la responsabilità dell’officina per attività svolte.\n6. Il cliente può chiedere la restituzione dei ricambi sostituiti quando consentito e se richiesti prima dello smaltimento; restano esclusi componenti soggetti a reso al fornitore, garanzia o obblighi di smaltimento.\n7. Pagamenti, consegna del veicolo, documenti fiscali e garanzie sono disciplinati dal preventivo, dalla documentazione consegnata e dalle norme applicabili. Restano impregiudicati i diritti inderogabili del cliente e le responsabilità previste dalla legge.\n\nFirma e data attestano l’accettazione della versione mostrata e delle sole autorizzazioni selezionate.`;
const defaultPrivacyNotice=`INFORMATIVA PRIVACY — modello da completare e verificare prima dell’uso\n\nTitolare del trattamento: [INSERIRE RAGIONE SOCIALE E CONTATTI DEL TITOLARE]. Contatto privacy: [INSERIRE EMAIL O RECAPITO].\n\nL’officina tratta i dati identificativi e di contatto, i dati del veicolo, le informazioni sull’intervento, le fotografie del mezzo e le firme per gestire la prenotazione, la diagnosi, la riparazione, la fatturazione e gli obblighi di legge. Le basi giuridiche applicabili vanno verificate dal titolare in relazione a ciascuna finalità.\n\nI dati sono accessibili al personale autorizzato e ai fornitori che erogano servizi necessari (ad esempio hosting, posta o consulenza contabile) secondo gli incarichi e le garanzie applicabili. [ELENCARE I FORNITORI, EVENTUALI TRASFERIMENTI E I CONTATTI PER ESERCITARE I DIRITTI].\n\nConservazione: [INDICARE DURATE O CRITERI DISTINTI PER DOCUMENTI CONTABILI, INTERVENTI, FOTO E CONSENSI]. L’interessato può esercitare i diritti previsti dalla normativa e rivolgersi al Garante per la protezione dei dati personali.\n\nMarketing e profilazione sono facoltativi, separati dalla riparazione e possono essere rifiutati senza conseguenze sul servizio. Il consenso può essere revocato in qualsiasi momento. Gli aggiornamenti email relativi al singolo intervento sono una scelta distinta e non equivalgono al marketing.`;
function signatureBuffer(value){const match=/^data:image\/(png|jpeg);base64,([A-Za-z0-9+/=]+)$/.exec(String(value||''));if(!match)return null;const data=Buffer.from(match[2],'base64');if(data.length<100||data.length>500000)return null;if(match[1]==='png'&&data.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))return data;if(match[1]==='jpeg'&&data[0]===255&&data[1]===216&&data[2]===255)return data;return null;}
function hashText(value){return crypto.createHash('sha256').update(String(value||'')).digest('hex');}
app.get('/tablet/work-orders/:id/acceptance',needAuth,allow('owner','admin','manager','reception','mechanic'),async(req,res,next)=>{try{const [order,settings,photos,acceptance,worker]=await Promise.all([pool.query(`SELECT w.*,v.plate,v.make,v.model,v.vin,c.name AS customer,c.email FROM work_orders w JOIN vehicles v ON v.id=w.vehicle_id JOIN customers c ON c.id=w.customer_id WHERE w.id=$1`,[req.params.id]),pool.query('SELECT business_name,repair_terms,privacy_notice,labs_3d_enabled,customer_display_enabled FROM workshop_settings WHERE id=1'),pool.query(`SELECT p.id,p.document_id,p.category,p.station,p.damage_marks,p.captured_at,d.file_name FROM intake_photos p JOIN documents d ON d.id=p.document_id WHERE p.work_order_id=$1 ORDER BY p.captured_at`,[req.params.id]),pool.query('SELECT id,accepted_at,road_test_decision,marketing_consent,profiling_consent,repair_email_consent FROM intake_acceptances WHERE work_order_id=$1 ORDER BY accepted_at DESC LIMIT 1',[req.params.id]),pool.query(`SELECT last_seen>now()-interval '2 minutes' AS online FROM photogrammetry_worker_status WHERE id=1`)]);if(!order.rowCount)return res.sendStatus(404);const w=order.rows[0],s=settings.rows[0],screenLink=String(req.query.customer_screen||''),exterior=photos.rows.filter(p=>p.category==='exterior'),complete=intakeStations.exterior.every(k=>exterior.some(p=>p.station===k)),coverageReady=checkPhotoCoverage(exterior).ready;const photoCards=photos.rows.map(p=>`<a class="intake-photo" href="/work-orders/${w.id}/documents/${p.document_id}" target="_blank"><img src="/work-orders/${w.id}/documents/${p.document_id}" alt="${esc(intakeLabels[p.station]||p.station)}"><span>${esc(intakeLabels[p.station]||p.station)}</span></a>`).join('');const reconRows=await pool.query(`SELECT id,status,current_stage,input_photo_count,error_message,queued_at,completed_at FROM vehicle_reconstructions WHERE work_order_id=$1 ORDER BY queued_at DESC LIMIT 1`,[w.id]);const recon=reconRows.rows[0];const reconstructionPanel=s.labs_3d_enabled?`<section class="card reconstruction-panel" data-work-order="${w.id}"><div class="section-heading"><div><h2>Ricostruzione fotogrammetrica</h2><p class="muted">COLMAP allinea le sole foto esterne; OpenMVS CPU calcola la scena densa, la mesh e le texture. Servono da 24 a 80 scatti nitidi e sovrapposti, almeno 3 da ogni area; worker ${worker.rows[0]?.online?'online':'offline'}.</p></div>${recon?.status==='complete'?`<a class="button primary" href="/work-orders/${w.id}/reconstruction/${recon.id}.glb" download>Scarica modello 3D GLB</a>`:''}</div>${recon?`<p class="reconstruction-state" data-job="${recon.id}" data-status="${recon.status}" data-stage="${esc(recon.current_stage||recon.status)}">Stato: <strong>${({queued:'In coda',running:'Ricostruzione in corso',complete:'Completata',failed:'Non riuscita'})[recon.status]}</strong> · ${recon.input_photo_count} foto · Fase: ${esc(reconstructionStages[recon.current_stage]||recon.current_stage||recon.status)} ${recon.status==='failed'?`<br><span class="error-text">${esc(recon.error_message)}</span>`:''}</p>`:'<p class="muted reconstruction-state" data-status="none">Nessuna ricostruzione avviata.</p>'}${recon?.status==='complete'?`<div class="model-view-wrap"><canvas id="reconstructed-model" data-src="/work-orders/${w.id}/reconstruction/${recon.id}.glb" aria-label="Modello ricostruito dell’auto, trascina per ruotare"></canvas><p id="model-status" class="muted">Caricamento modello…</p></div>`:''}${(!recon||['failed','complete'].includes(recon.status))?`<form method="post" action="/tablet/work-orders/${w.id}/reconstruction">${formToken(req)}<button class="button primary" ${coverageReady?'':'disabled'}>Crea modello 3D reale dalle foto (${exterior.length} esterne)</button></form>`:''}<p class="muted">La qualità dipende da sovrapposizione, luce, dettagli e sfondo; il veicolo non è una superficie rigida uniforme, quindi la mesh può avere lacune o deformazioni. La geometria non sostituisce l’ispezione tecnica.</p></section>`:'';const prefix=page('Accettazione tablet',`${screenLink?`<section class="card"><h2>Schermo cliente</h2><p>Apri questo link sul monitor o tablet mostrato al cliente. Scade dopo 2 ore.</p><p><a href="${esc(screenLink)}" target="_blank" rel="noopener">${esc(screenLink)}</a></p><a class="button primary" href="${esc(screenLink)}" target="_blank" rel="noopener">Apri schermo cliente</a></section>`:''}<section class="card intake-header"><div><span class="eyebrow">GO-${w.id} · ${esc(w.plate)}</span><h2>${esc(w.make)} ${esc(w.model)}</h2><p>${esc(w.customer)} · ${esc(w.complaint||'Problema non descritto')}</p></div><div class="actions"><a class="button" href="/work-orders/${w.id}">Torna all’ordine</a><a class="button" href="/tablet/work-orders/${w.id}/acceptance.pdf?paper=1" target="_blank">Stampa modulo PDF</a>${s.customer_display_enabled?`<form method="post" action="/work-orders/${w.id}/customer-screen">${formToken(req)}<button class="button primary">Invia documenti allo schermo cliente</button></form>`:''}</div></section><section class="card intake-capture"><div class="capture-vehicle"><div class="section-heading"><div><h2>Foto guidate del veicolo</h2><p class="muted">Seleziona un’area per fotografarla. I cerchi arancioni indicano gli angoli richiesti. Per il modello 3D acquisisci almeno 3 scatti sovrapposti per area (24 in totale).</p></div><span class="badge ${complete?'good':'warning'}">${intakeStations.exterior.filter(k=>exterior.some(p=>p.station===k)).length}/8 aree · ${exterior.length} foto</span></div><div class="vehicle-figure"><svg id="vehicle-map" viewBox="0 0 420 650" role="img" aria-label="Sagoma vista dall’alto: tocca un’area per fotografarla o segnalare un danno"><path class="vehicle-body" d="M145 22 Q210 0 275 22 L298 64 Q337 88 345 155 L365 470 Q360 535 322 565 L300 615 Q210 645 120 615 L98 565 Q60 535 55 470 L75 155 Q83 88 122 64 Z"/><path class="vehicle-glass" d="M137 88 Q210 68 283 88 L306 175 Q210 198 114 175 Z M111 205 Q210 226 309 205 L322 420 Q210 398 98 420 Z M101 448 Q210 426 319 448 L295 535 Q210 554 125 535 Z"/><path class="vehicle-line" d="M80 187 Q210 210 340 187 M75 438 Q210 412 345 438 M97 555 Q210 583 323 555"/><g id="damage-layer"></g>${[['front',210,28],['front_right',325,118],['right',357,313],['rear_right',330,505],['rear',210,625],['rear_left',90,505],['left',63,313],['front_left',95,118]].map(([key,x,y])=>`<g class="photo-station ${exterior.some(p=>p.station===key)?'captured':''}" data-station="${key}" tabindex="0" role="button" aria-label="Fotografa ${intakeLabels[key]}"><circle cx="${x}" cy="${y}" r="25"/><text x="${x}" y="${y+5}">${exterior.some(p=>p.station===key)?'✓':'+'}</text></g>`).join('')}</svg></div><div class="station-list">${intakeStations.exterior.map(key=>`<button type="button" class="button small ${exterior.some(p=>p.station===key)?'is-done':''}" data-select-station="${key}">${intakeLabels[key]} ${exterior.some(p=>p.station===key)?'✓':'○'}</button>`).join('')}</div><p class="muted">Tocca la sagoma nella posizione del danno per aggiungere un segno. Il segno resta associato alla prossima foto scattata.</p></div><div class="camera-panel"><div class="camera-frame"><video id="intake-camera" autoplay playsinline muted></video><canvas id="capture-canvas" hidden></canvas><div id="camera-placeholder">Attiva la fotocamera del tablet oppure usa “Scegli foto”</div></div><div class="camera-controls"><label>Categoria<select id="photo-category"><option value="exterior">Esterni</option><option value="interior">Interni</option><option value="dashboard">Cruscotto</option></select></label><label>Posizione<select id="photo-station">${Object.entries(intakeLabels).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label><button class="button primary" id="capture-photo" type="button">Scatta e salva foto</button><label class="button file-pick">Scegli foto<input id="file-photo" type="file" accept="image/*" capture="environment"></label><p class="muted" id="camera-status" aria-live="polite">La fotocamera richiede HTTPS e il permesso del browser. Se non disponibile, usa Scegli foto.</p></div></div></section><section class="card"><div class="section-heading"><div><h2>Foto già registrate</h2><p class="muted">Interni e cruscotto sono esclusi dalla copertura esterna.</p></div>${s.labs_3d_enabled?`<button id="view-360" class="button" type="button" ${complete?'':'disabled'}>Visualizza sequenza 360°</button>`:''}</div><div class="intake-photo-grid">${photoCards||'<p class="muted">Nessuna foto acquisita.</p>'}</div><div id="view360-modal" class="view360-modal" hidden><button id="close-360" class="button">Chiudi</button><p>Vista rotabile dalle 8 foto esterne. Non è una ricostruzione geometrica 3D.</p><div id="view360-stage"></div><input id="view360-slider" type="range" min="0" max="7" value="0" aria-label="Ruota vista veicolo"></div></section>${reconstructionPanel}<section class="card"><h2>Firma e autorizzazioni</h2><p class="muted">Le condizioni e l’informativa vengono salvate come copie immutabili. La firma disegnata è una firma elettronica semplice, non una firma qualificata. Completa i campi privacy dell’officina e sottoponi i testi a verifica professionale.</p><form id="acceptance-form" data-work-order="${w.id}" data-csrf="${esc(csrf(req))}" data-terms="${esc(s.repair_terms||defaultRepairTerms)}" data-privacy="${esc(s.privacy_notice||defaultPrivacyNotice)}"><label>Nome del cliente che firma<input name="signed_name" required value="${esc(w.customer)}"></label><label class="accept-row"><input type="checkbox" name="terms_accepted" required> Accetto le condizioni del servizio di riparazione mostrate</label><label class="accept-row"><input type="checkbox" name="privacy_acknowledged" required> Confermo di aver ricevuto e potuto leggere l’informativa privacy (presa visione, non consenso generale)</label><label class="accept-row"><input type="checkbox" name="road_test_authorized"> Autorizzo una prova su strada limitata alle verifiche pertinenti. Se non selezionata, il rifiuto verrà registrato e alcuni sintomi potrebbero non essere verificabili su strada.</label><label class="accept-row"><input type="checkbox" name="repair_email_consent"> Desidero ricevere via email aggiornamenti relativi a questo intervento (facoltativo)</label><label class="accept-row"><input type="checkbox" name="marketing_consent"> Acconsento a ricevere comunicazioni promozionali via email (facoltativo, revocabile)</label><label class="accept-row"><input type="checkbox" name="profiling_consent"> Acconsento alla profilazione per offerte personalizzate (facoltativo, revocabile)</label><details><summary>Leggi condizioni di riparazione</summary><p>${esc(s.repair_terms||defaultRepairTerms)}</p></details><details><summary>Leggi informativa privacy</summary><p>${esc(s.privacy_notice||defaultPrivacyNotice)}</p></details><div class="signature-grid"><label>Firma cliente — condizioni<canvas class="signature-pad" data-signature="terms"></canvas><button type="button" class="button small clear-signature">Cancella firma</button></label><label>Firma cliente — informativa privacy<canvas class="signature-pad" data-signature="privacy"></canvas><button type="button" class="button small clear-signature">Cancella firma</button></label></div><label>Servizio a prezzo preaccordato (facoltativo)<input name="preagreed_service" placeholder="Es. tagliando standard"></label><label>Prezzo preventivato IVA inclusa (€)<input name="preagreed_price" type="number" min="0" step="0.01"></label><button class="button primary" type="submit">Salva firme e accettazione</button><p id="acceptance-status" role="status" aria-live="polite"></p></form></section><section class="card"><h2>Storico accettazione</h2>${acceptance.rows[0]?`<p>Ultima firma: ${fmtDate(acceptance.rows[0].accepted_at)} · Prova su strada: ${acceptance.rows[0].road_test_decision==='authorized'?'autorizzata':'rifiutata'}</p>`:'<p class="muted">Nessuna firma registrata.</p>'}</section>`,req.session.user,'orders');res.send(prefix.replace('<head>','<head><link rel="stylesheet" href="/intake.css">').replace('</body>',`${recon?.status==='complete'?'<script defer src="/glb-viewer.js"></script>':''}<script defer src="/intake.js"></script></body>`));}catch(e){next(e);}});
const intakePhotoUpload=multer({storage:multer.memoryStorage(),limits:{fileSize:8*1024*1024,files:1}});
app.post('/tablet/work-orders/:id/photos',needAuth,allow('owner','admin','manager','reception','mechanic'),intakePhotoUpload.single('photo'),async(req,res,next)=>{try{const file=req.file,category=String(req.body.category||''),station=String(req.body.station||''),marks=JSON.parse(String(req.body.damage_marks||'[]'));if(!file||!intakeStations[category]?.includes(station))return res.status(400).json({error:'Seleziona una categoria e una posizione valida.'});if(!['image/jpeg','image/png','image/webp'].includes(file.mimetype))return res.status(400).json({error:'Formato immagine non supportato.'});const valid=(file.mimetype==='image/png'&&file.buffer.subarray(0,8).equals(Buffer.from([137,80,78,71,13,10,26,10])))||(file.mimetype==='image/jpeg'&&file.buffer[0]===255&&file.buffer[1]===216&&file.buffer[2]===255)||(file.mimetype==='image/webp'&&file.buffer.toString('ascii',8,12)==='WEBP');if(!valid)return res.status(400).json({error:'Il file selezionato non è un’immagine valida.'});if(!Array.isArray(marks)||marks.length>20||marks.some(m=>!Number.isFinite(m.x)||!Number.isFinite(m.y)||m.x<0||m.x>1||m.y<0||m.y>1))return res.status(400).json({error:'Segni danno non validi.'});const order=await pool.query('SELECT id FROM work_orders WHERE id=$1',[req.params.id]);if(!order.rowCount)return res.sendStatus(404);const d=await pool.query(`INSERT INTO documents(work_order_id,document_type,file_name,mime_type,file_data,created_by) VALUES($1,'vehicle_photo',$2,$3,$4,$5) RETURNING id`,[req.params.id,`accettazione-${category}-${station}-${Date.now()}.${file.mimetype==='image/png'?'png':file.mimetype==='image/webp'?'webp':'jpg'}`,file.mimetype,file.buffer,req.session.user.id]);const p=await pool.query(`INSERT INTO intake_photos(work_order_id,document_id,category,station,damage_marks,captured_by) VALUES($1,$2,$3,$4,$5::jsonb,$6) RETURNING id`,[req.params.id,d.rows[0].id,category,station,JSON.stringify(marks),req.session.user.id]);res.json({ok:true,id:p.rows[0].id,label:intakeLabels[station],category,station});}catch(e){if(e instanceof SyntaxError)return res.status(400).json({error:'Annotazioni foto non valide.'});next(e);}});
