app.post('/work-orders/:id/customer-screen',needAuth,allow('owner','admin','manager','reception'),async(req,res,next)=>{try{const setting=await pool.query('SELECT customer_display_enabled,repair_terms,privacy_notice FROM workshop_settings WHERE id=1');if(!setting.rows[0]?.customer_display_enabled)throw new Error('Attiva prima Schermo cliente in Impostazioni → Labs.');const t=setting.rows[0].repair_terms||defaultRepairTerms,p=setting.rows[0].privacy_notice||defaultPrivacyNotice;const raw=crypto.randomBytes(32).toString('base64url'),tokenHash=crypto.createHash('sha256').update(raw).digest('hex');const row=await pool.query(`INSERT INTO customer_screen_sessions(work_order_id,token_hash,mode,terms_text,privacy_text,created_by,expires_at) VALUES($1,$2,'consent',$3,$4,$5,now()+interval '2 hours') RETURNING id`,[req.params.id,tokenHash,t,p,req.session.user.id]);await pool.query(`INSERT INTO audit_log(user_id,action,entity_type,entity_id,details) VALUES($1,'open_customer_screen','work_order',$2,$3)`,[req.session.user.id,String(req.params.id),JSON.stringify({session_id:row.rows[0].id,expires_in_hours:2})]);flash(req,'Schermo cliente pronto. Apri il collegamento su un monitor/tablet dedicato: il link scade tra 2 ore.');res.redirect(`/tablet/work-orders/${req.params.id}/acceptance?customer_screen=${encodeURIComponent(`/customer-screen/${raw}`)}`);}catch(e){flash(req,e.message);res.redirect(`/tablet/work-orders/${req.params.id}/acceptance`);}});
