app.get('/tablet/work-orders/:id/reconstruction/status',needAuth,allow('owner','admin','manager','reception','mechanic'),async(req,res,next)=>{try{const [r,worker]=await Promise.all([pool.query(`SELECT id,status,current_stage,input_photo_count,error_message,queued_at,started_at,completed_at FROM vehicle_reconstructions WHERE work_order_id=$1 ORDER BY queued_at DESC LIMIT 1`,[req.params.id]),pool.query(`SELECT last_seen>now()-interval '2 minutes' AS online FROM photogrammetry_worker_status WHERE id=1`)]);res.json({...r.rows[0]||{status:'none'},worker_online:Boolean(worker.rows[0]?.online)});}catch(e){next(e);}});
app.get('/work-orders/:id/reconstruction/:jobId.glb',needAuth,allow('owner','admin','manager','reception','mechanic'),async(req,res,next)=>{try{const r=await pool.query(`SELECT result_glb,status FROM vehicle_reconstructions WHERE id=$1 AND work_order_id=$2`,[req.params.jobId,req.params.id]);if(!r.rowCount)return res.sendStatus(404);if(r.rows[0].status!=='complete'||!r.rows[0].result_glb)return res.status(409).send('Ricostruzione non ancora disponibile.');res.type('model/gltf-binary').set('Content-Disposition',`inline; filename="GO-${req.params.id}-veicolo.glb"`).set('Cache-Control','private, no-store').send(r.rows[0].result_glb);}catch(e){next(e);}});
app.get('/tablet/work-orders/:id/acceptance.pdf',needAuth,allow('owner','admin','manager','reception'),async(req,res,next)=>{try{const q=await pool.query(`SELECT w.*,v.plate,v.make,v.model,v.vin,c.name AS customer,c.email,c.phone,s.business_name,s.address,s.phone AS workshop_phone,s.email AS workshop_email,s.vat_number,s.tax_code,s.logo_data,s.repair_terms,s.privacy_notice FROM work_orders w JOIN vehicles v ON v.id=w.vehicle_id JOIN customers c ON c.id=w.customer_id CROSS JOIN workshop_settings s WHERE w.id=$1 AND s.id=1`,[req.params.id]);if(!q.rowCount)return res.sendStatus(404);const d=q.rows[0],paper=req.query.paper==='1',t=d.repair_terms||defaultRepairTerms,p=d.privacy_notice||defaultPrivacyNotice;const pdf=new PDFDocument({size:'A4',margin:42,bufferPages:true});const chunks=[];pdf.on('data',x=>chunks.push(x));pdf.on('error',next);pdf.on('end',async()=>{try{const bytes=Buffer.concat(chunks);await pool.query(`INSERT INTO documents(work_order_id,document_type,file_name,mime_type,file_data,created_by) VALUES($1,$2,$3,'application/pdf',$4,$5)`,[d.id,paper?'intake_paper_pdf':'intake_acceptance_pdf',`GO-${d.id}-accettazione-${paper?'carta':'cliente'}.pdf`,bytes,req.session.user.id]);res.type('application/pdf').set('Content-Disposition',`inline; filename="GO-${d.id}-accettazione.pdf"`).send(bytes);}catch(e){next(e);}});drawWorkshopLogo(pdf,d.logo_data);pdf.fillColor('#202a39').font('Helvetica-Bold').fontSize(16).text(d.business_name,190,42,{width:360});pdf.font('Helvetica').fontSize(8).fillColor('#667085').text([d.address,d.workshop_phone,d.workshop_email,d.vat_number?`P. IVA ${d.vat_number}`:''].filter(Boolean).join(' · '),190,68,{width:360});pdf.moveTo(42,105).lineTo(553,105).strokeColor('#ef6b22').lineWidth(2).stroke();pdf.moveDown(3).fillColor('#202a39').font('Helvetica-Bold').fontSize(15).text(`SCHEDA DI ACCETTAZIONE · GO-${d.id}`,42,122);pdf.moveDown(.8).font('Helvetica').fontSize(10);for(const [l,v] of [['Cliente',d.customer],['Contatti',[d.phone,d.email].filter(Boolean).join(' · ')||'—'],['Veicolo',`${d.plate} · ${d.make} ${d.model}`],['VIN',d.vin||'—'],['Ingresso / km',`${fmtDate(d.created_at)} · ${Number(d.mileage_in).toLocaleString('it-IT')} km`],['Problema descritto',d.complaint||'—'],['Prezzo preaccordato','Servizio: ____________________________________   Prezzo IVA inclusa: € __________']]){pdf.font('Helvetica-Bold').text(`${l}: `,{continued:true});pdf.font('Helvetica').text(String(v));pdf.moveDown(.35);}pdf.moveDown(.5).font('Helvetica-Bold').text('Condizioni di riparazione');pdf.moveDown(.3).font('Helvetica').fontSize(7.5).text(t,{width:510,paragraphGap:2});pdf.moveDown(.4).font('Helvetica-Bold').fontSize(9).text('Informativa privacy');pdf.moveDown(.3).font('Helvetica').fontSize(7.5).text(p,{width:510,paragraphGap:2});pdf.moveDown(.6).font('Helvetica-Bold').fontSize(9).text('Scelte del cliente');pdf.font('Helvetica').fontSize(8).text('□ Prova su strada autorizzata     □ Prova su strada rifiutata (il test dinamico non sarà effettuato; alcuni sintomi potrebbero restare non verificati).');pdf.text('□ Aggiornamenti email per questo intervento     □ Marketing email facoltativo     □ Profilazione facoltativa');pdf.moveDown(.8).fontSize(8).text('Firma condizioni: ____________________________________     Firma presa visione privacy: ____________________________________');pdf.text('Nome: ______________________________________________     Data: ____ / ____ / ______');pdf.moveDown(.6).fontSize(7).fillColor('#667085').text('Il rifiuto della prova su strada non è una rinuncia generale ai diritti del cliente e non esclude le responsabilità dell’officina previste dalla legge. Documento gestionale; i modelli devono essere verificati dal titolare e dai consulenti incaricati.',{width:510});pdf.end();}catch(e){next(e);}});

app.get('/work-orders/:id/pdf',needAuth,async(req,res,next)=>{
  try{
    const r=await pool.query(`SELECT w.*,v.plate,v.make,v.model,v.vin,c.name AS customer,c.phone,c.email,s.business_name,s.address,s.phone AS workshop_phone,s.email AS workshop_email,s.vat_number,s.logo_path,s.logo_data FROM work_orders w JOIN vehicles v ON v.id=w.vehicle_id JOIN customers c ON c.id=w.customer_id CROSS JOIN workshop_settings s WHERE w.id=$1`,[req.params.id]);
    if(!r.rowCount)return res.sendStatus(404);
    const d=r.rows[0];
    const pdf=new PDFDocument({size:'A4',margin:48});
    archivePdf(pdf,req,res,next,{documentType:'work_order_intake_pdf',filename:`GO-Ordine-${d.id}.pdf`,workOrderId:d.id});
    drawWorkshopLogo(pdf,d.logo_data);
    pdf.fillColor('#202a39').fontSize(17).font('Helvetica-Bold').text(d.business_name,205,48,{width:342});
    pdf.fillColor('#667085').fontSize(8).font('Helvetica').text([d.address,d.workshop_phone,d.workshop_email,d.vat_number?`P. IVA ${d.vat_number}`:''].filter(Boolean).join(' · '),205,74,{width:342});
    pdf.y=115;pdf.strokeColor('#ef6b22').lineWidth(2).moveTo(48,pdf.y).lineTo(547,pdf.y).stroke();
    pdf.moveDown(1).fillColor('#202a39').fontSize(17).font('Helvetica-Bold').text(`SCHEDA DI PRESA IN CARICO · GO-${d.id}`);
    pdf.moveDown(.8).fontSize(10).font('Helvetica');
    const rows=[['Cliente',d.customer],['Contatto',[d.phone,d.email].filter(Boolean).join(' · ')||'—'],['Veicolo',`${d.plate} · ${d.make} ${d.model}`],['VIN',d.vin||'—'],['Data ingresso',fmtDate(d.created_at)],['Chilometraggio',`${Number(d.mileage_in).toLocaleString('it-IT')} km`],['Livello carburante / carica',d.fuel_level||'—'],['Problema segnalato',d.complaint||'—'],['Note',d.notes||'—']];
    for(const [label,value] of rows){pdf.font('Helvetica-Bold').text(`${label}: `,{continued:true});pdf.font('Helvetica').text(String(value));pdf.moveDown(.45);}
    pdf.moveDown(1).text('Condizioni del veicolo e autorizzazione alla diagnosi/lavorazioni approvate:');
    pdf.moveDown(3).text('Firma cliente: ______________________________     Data: ____ / ____ / ______');
    pdf.moveDown(3).fillColor('#667085').fontSize(8).text('Documento gestionale di presa in carico. Gli interventi devono essere eseguiti secondo il preventivo approvato e le condizioni sottoscritte.');
    pdf.end();
  }catch(e){next(e);}
});

app.use((err,req,res,_next)=>{console.error(err);if(res.headersSent)return;const uploadError=String(err.code||'').startsWith('LIMIT_');const status=err.code==='23503'||err.code==='22P02'||uploadError?400:500;const message=err.code==='LIMIT_FILE_SIZE'?'Un file supera il limite di dimensione.':err.code==='LIMIT_FILE_COUNT'?'Hai selezionato troppi file.':uploadError?'Il file selezionato non è valido.':err.message;res.status(status).send(page(status===500?'Errore':'Dati non validi',`<section class="card"><h2>${status===500?'Si è verificato un errore':'Controlla i dati inseriti'}</h2><p>${status===500?'Riprova. Se il problema continua, contatta l’amministratore.':esc(message)}</p><a class="button" href="javascript:history.back()">Torna indietro</a></section>`,req.session?.user));});

const port=Number(process.env.PORT||10000);
app.listen(port,'0.0.0.0',()=>console.log(`GO Gestione Officina in ascolto sulla porta ${port}`));
